async ({ shell: { execFile, exec } }, body: string) => {
  const pr = await execFile("gh", ["pr", "create", "--base", "main", "--head", "fix/nested-run-guard", "--title", "fix: stop a pi-action run that the agent starts inside a run", "--body", body], { timeoutMs: 60000 });
  const url = pr.stdout.trim();
  const n = url.split("/").pop();
  const fix = await exec(`gh pr view ${n} --json body -q .body | sed 's/(#NN)/(#${n})/' > /tmp/b.md && gh pr edit ${n} --body-file /tmp/b.md`, { timeoutMs: 60000 });
  return url + pr.stderr + fix.stderr;
}
